async function api(url,options={},csrfRetry=false){
 const headers={...(options.headers||{})};
 if(options.body&&!(options.body instanceof FormData)){headers['Content-Type']='application/json';}
 if(options.method&&options.method!=='GET')headers['X-CSRF-Token']=csrf;
 const request={...options,headers,credentials:'same-origin'};
 if(options.body&&!(options.body instanceof FormData))request.body=JSON.stringify(options.body);
 const r=await fetch('/api'+url,request);
 if(!r.ok){let data;try{data=await r.json();}catch{data={};}
  if(r.status===403&&!csrfRetry&&options.method&&options.method!=='GET'&&/session expir/i.test(data.erreur||'')){
   const renewal=await fetch('/api/auth/session',{credentials:'same-origin',cache:'no-store'});
   if(renewal.ok){const info=await renewal.json();csrf=info.csrf||'';if(info.authenticated)return api(url,options,true);}
   throw new Error('Votre session a expiré. Rechargez la page pour vous reconnecter. Vos données restent enregistrées.');
  }
  throw new Error(data.erreur||'Service indisponible ('+r.status+').');
 }
 return r.status===204?null:r.json();
}
